#!/usr/bin/env python3
"""
build_llm_observatory_project.py
=================================

Single-cell repository generator for the LLM Performance & Cost Observatory
portfolio project.

Paste this entire script into ONE Google Colab cell (or run it locally with
`python build_llm_observatory_project.py`) and execute it once. It will:

  1. Create the complete project directory structure.
  2. Write every source file, test file, dataset file, README, requirements,
     .gitignore, and .env.example.
  3. Create the results/ and results/plots/ output directories.
  4. Install project dependencies.
  5. Run the pytest test suite.
  6. Run the benchmark end-to-end, generating CSV/JSON/PNG results.
  7. Package the whole project into a ZIP archive.

Output locations:
    /content/llm-performance-observatory/        (or ./llm-performance-observatory
                                                    outside Colab)
    /content/llm-performance-observatory.zip      (or ./llm-performance-observatory.zip)

Every project file is embedded below as base64-encoded text and decoded at
write time. This guarantees byte-for-byte reproduction of each file with
zero risk of quote-escaping bugs, while every file written to disk is
completely ordinary, human-readable Python / Markdown / JSON source -
nothing about the generated repository itself is encoded in any way.
"""

import base64
import os
import subprocess
import sys
import zipfile

# Detect Colab vs local execution and pick a sensible project root.
IN_COLAB = os.path.isdir("/content")
PROJECT_ROOT = "/content/llm-performance-observatory" if IN_COLAB else os.path.join(
    os.getcwd(), "llm-performance-observatory"
)
ZIP_PATH = PROJECT_ROOT + ".zip"

DIRS = ['src', 'data', 'results', 'results/plots', 'tests']

# (relative_path, base64_encoded_content)
FILES_B64 = [
    ('README.md', ''),
    ('requirements.txt', ''),
    ('.gitignore', ''),
    ('.env.example', ''),
    ('run_benchmark.py', ''),
    ('src/__init__.py', 'IiIiTExNIFBlcmZvcm1hbmNlICYgQ29zdCBPYnNlcnZhdG9yeSAtIGNvcmUgcGFja2FnZS4iIiIKCl9fdmVyc2lvbl9fID0gIjEuMC4wIgo='),
    ('src/config.py', ''),
    ('src/models.py', ''),
    ('src/dataset.py', ''),
    ('src/providers.py', ''),
    ('src/evaluator.py', ''),
    ('src/metrics.py', ''),
    ('src/benchmark.py', ''),
    ('src/reporting.py', ''),
    ('src/observability.py', ''),
    ('data/benchmark_dataset.json', ''),
    ('tests/test_metrics.py', ''),
    ('tests/test_cost.py', ''),
    ('tests/test_evaluator.py', ''),
    ('tests/test_benchmark.py', ''),
]


def write_project_files():
    print(f"Creating project at: {PROJECT_ROOT}")
    for d in DIRS:
        os.makedirs(os.path.join(PROJECT_ROOT, d), exist_ok=True)

    # .gitkeep placeholders so empty result directories are preserved.
    open(os.path.join(PROJECT_ROOT, "results", ".gitkeep"), "w").close()
    open(os.path.join(PROJECT_ROOT, "results", "plots", ".gitkeep"), "w").close()

    for rel_path, b64_content in FILES_B64:
        full_path = os.path.join(PROJECT_ROOT, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        content = base64.b64decode(b64_content.encode("ascii"))
        with open(full_path, "wb") as f:
            f.write(content)
        print(f"  wrote {rel_path} ({len(content)} bytes)")

    print("All project files written.")


def install_requirements():
    req_path = os.path.join(PROJECT_ROOT, "requirements.txt")
    print("\nInstalling requirements (this can take a minute)...")
    cmd = [sys.executable, "-m", "pip", "install", "-q", "-r", req_path]
    result = subprocess.run(cmd)
    if result.returncode != 0:
        print("WARNING: pip install reported a non-zero exit code. "
              "Core local-mode functionality may still work if numpy/"
              "matplotlib/sentence-transformers are already available.")


def run_tests():
    print("\nRunning test suite...")
    cmd = [sys.executable, "-m", "pytest", "tests/", "-v"]
    subprocess.run(cmd, cwd=PROJECT_ROOT)


def run_benchmark():
    print("\nRunning benchmark (LOCAL_SIMULATION mode, no API key required)...")
    cmd = [sys.executable, "run_benchmark.py"]
    subprocess.run(cmd, cwd=PROJECT_ROOT)


def create_zip():
    print(f"\nCreating ZIP archive at: {ZIP_PATH}")
    if os.path.exists(ZIP_PATH):
        os.remove(ZIP_PATH)
    with zipfile.ZipFile(ZIP_PATH, "w", zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(PROJECT_ROOT):
            dirs[:] = [d for d in dirs if d not in ("__pycache__", ".pytest_cache")]
            for fname in files:
                if fname.endswith((".pyc", ".pyo")):
                    continue
                full_path = os.path.join(root, fname)
                arcname = os.path.join(
                    "llm-performance-observatory",
                    os.path.relpath(full_path, PROJECT_ROOT),
                )
                zf.write(full_path, arcname)
    print("ZIP archive created.")


def main():
    write_project_files()
    install_requirements()
    run_tests()
    run_benchmark()
    create_zip()

    print("\n" + "=" * 60)
    print("DONE")
    print("=" * 60)
    print(f"Project directory: {PROJECT_ROOT}")
    print(f"ZIP archive:       {ZIP_PATH}")
    print("\nNext steps:")
    print("  1. Inspect results/ (CSV, JSON) and results/plots/ (PNG) inside the project directory.")
    print("  2. Download the ZIP and/or the project folder.")
    print("  3. Upload the extracted project to a new GitHub repository.")
    print("=" * 60)


if __name__ == "__main__":
    main()
